-- sys_admin_log DDL
DROP TABLE IF EXISTS "sys_admin_log";
CREATE TABLE "sys_admin_log" (
"id" int8 NOT NULL GENERATED BY DEFAULT AS IDENTITY,
"title" varchar(50) NOT NULL,
"method" varchar(255) NOT NULL,
"account" varchar(50) NOT NULL,
"request_url" varchar(255) NOT NULL,
"request_ip" varchar(128) NOT NULL,
"request_body" varchar(2000) NOT NULL,
"request_header" varchar(255),
"response" varchar(2000),
"state" int2 NOT NULL DEFAULT 1,
"message" varchar(255),
"times" int8 NOT NULL,
"request_time" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT "sys_admin_log_pk" PRIMARY KEY ("id"));

-- sys_api_log DDL
DROP TABLE IF EXISTS "sys_api_log";
CREATE TABLE "sys_api_log" (
"id" int8 NOT NULL GENERATED BY DEFAULT AS IDENTITY,
"method" varchar(255) NOT NULL,
"user_id" int8,
"request_url" varchar(255) NOT NULL,
"request_ip" varchar(128) NOT NULL,
"request_body" varchar(2000) NOT NULL,
"request_header" varchar(255),
"response" varchar(2000),
"state" int2 NOT NULL DEFAULT 1,
"message" varchar(255),
"times" int8 NOT NULL,
"request_time" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT "sys_api_log_pk" PRIMARY KEY ("id"));

-- sys_auth DDL
DROP TABLE IF EXISTS "sys_auth";
