"title" varchar(50) NOT NULL,
"code" varchar(50),
"name" varchar(50) NOT NULL,
"auth_type" int2 NOT NULL,
"sort" int4,
"icon" varchar(50),
"path" varchar(255),
"component" varchar(255),
"frame_flag" int2 NOT NULL DEFAULT 0,
"frame_url" varchar(255),
