"state" int2 NOT NULL,
"create_user" varchar(50) NOT NULL,
"create_time" timestamptz(6) NOT NULL,
"update_user" varchar(50),
"update_time" timestamptz(6),
"remark" varchar(255),
CONSTRAINT "sys_auth_pk" PRIMARY KEY ("id"));

